// Degenesis timeline and order reads (audit 4f4aa8377, DegenerusGameDegenesisModule + GameTimeLib).
//
// Day index 1 is the deploy day: normal ETH buys earn credit (25% of spend) but the sale is closed.
// Indices 2-8 are Degenesis days 1-7: buyDegenesisBox is open and each day is one cohort, sealed at
// its day's end and settled later by mineFlip. The level stays 0 through index 8; index 9
// (MAIN_LAUNCH_DAY) is the first level advance and the first daily jackpot. The clock is the
// deployment's own day clock (VOLUME_WINDOW: the 1200 s testnet day, 86400 s on mainnet).
import { VOLUME_WINDOW } from './chain-config.js';

/** A game day with no daily jackpot by design: index 1-8. */
export function isDegenesisGameDay(day) {
  const n = Number(day);
  return Number.isInteger(n) && n >= 1 && n < MAIN_LAUNCH_DAY;
}

/** First Degenesis sale day (GameTimeLib.DEGENESIS_START_DAY). */
export const DEGENESIS_START_DAY = 2;
/** First post-Degenesis day; its opening request rolls the first daily jackpot. */
export const MAIN_LAUNCH_DAY = DEGENESIS_START_DAY + 7;
/** Number of daily cohorts. */
export const DEGENESIS_DAYS = 7;

let _nowSec = () => Date.now() / 1000;
/** Wall-clock seconds the purchase surfaces evaluate the window at. */
export function degenesisNow() { return _nowSec(); }
/** Tests pin the window without stubbing Date.now for every other timer; returns the previous clock. */
export function __setDegenesisNowForTest(fn) {
  const previous = _nowSec;
  _nowSec = typeof fn === 'function' ? fn : () => Date.now() / 1000;
  return previous;
}

/** Wall-clock game day index from the deployment clock, or null before the clock is configured. */
export function degenesisWallDay(nowSec, clock = VOLUME_WINDOW) {
  const anchor = Number(clock?.anchor);
  const period = Number(clock?.period);
  const boundary = clock?.deployDayBoundary == null ? NaN : Number(clock.deployDayBoundary);
  if (!Number.isFinite(anchor) || !(period > 0) || !Number.isFinite(boundary)) return null;
  return Math.max(1, Math.floor((Number(nowSec) - anchor) / period) - boundary + 1);
}

/** Seconds until the next day boundary on the deployment clock. */
export function secondsToNextDay(nowSec, clock = VOLUME_WINDOW) {
  const anchor = Number(clock?.anchor);
  const period = Number(clock?.period);
  if (!Number.isFinite(anchor) || !(period > 0)) return null;
  const into = ((Number(nowSec) - anchor) % period + period) % period;
  return period - into;
}

/**
 * Where the deployment is on the Degenesis timeline.
 * phase: 'credit' (deploy day: earn credit, sale opens tomorrow), 'sale' (Degenesis day 1-7),
 * 'launched' (index 9 on: the main game), or null without a clock.
 */
export function degenesisWindow(nowSec, clock = VOLUME_WINDOW) {
  const day = degenesisWallDay(nowSec, clock);
  if (day == null) return { day: null, phase: null, degenesisDay: null, secondsLeft: null, saleOpen: false };
  const saleOpen = day >= DEGENESIS_START_DAY && day < MAIN_LAUNCH_DAY;
  const phase = day < DEGENESIS_START_DAY ? 'credit' : saleOpen ? 'sale' : 'launched';
  return {
    day,
    phase,
    saleOpen,
    degenesisDay: saleOpen ? day - DEGENESIS_START_DAY + 1 : null,
    // Seconds until today's cohort seals (sale) or the sale opens (credit day).
    secondsLeft: phase === 'launched' ? null : secondsToNextDay(nowSec, clock),
  };
}

/** True while the level cannot have advanced yet (index <= 8): level 0 with no jackpots is expected. */
export function inDegenesisPeriod(nowSec, clock = VOLUME_WINDOW) {
  const day = degenesisWallDay(nowSec, clock);
  return day != null && day < MAIN_LAUNCH_DAY;
}

/** Live UI gate: the Degenesis layout runs through the sale period. */
export function isDegenesisActive(nowSec = degenesisNow(), clock = VOLUME_WINDOW) {
  return inDegenesisPeriod(nowSec, clock);
}

/**
 * Exact display-ETH text (mainnet-equivalent) -> deployed wei, or null when it is not a plain
 * decimal or does not land on a whole deployed wei. Never rounds through a float.
 */
export function ethTextToWei(text, divisor = 1n) {
  const raw = String(text ?? '').trim();
  if (!/^\d*(\.\d{0,18})?$/.test(raw) || raw === '' || raw === '.') return null;
  const [whole, frac = ''] = raw.split('.');
  const full = BigInt(whole || '0') * 10n ** 18n + BigInt((frac + '0'.repeat(18)).slice(0, 18));
  const scale = BigInt(divisor);
  return full % scale === 0n ? full / scale : null;
}

/** "3h 05m" / "12m 30s" / "45s". */
export function formatDegenesisCountdown(seconds) {
  const s = Math.max(0, Math.floor(Number(seconds) || 0));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), r = s % 60;
  if (h > 0) return `${h}h ${String(m).padStart(2, '0')}m`;
  if (m > 0) return `${m}m ${String(r).padStart(2, '0')}s`;
  return `${r}s`;
}

/** One-line window label for the purchase surfaces. */
export function degenesisWindowLabel(window) {
  if (!window?.phase) return '';
  const left = window.secondsLeft == null ? '' : ` · ${formatDegenesisCountdown(window.secondsLeft)}`;
  if (window.phase === 'credit') return `DEGENESIS OPENS IN${left.replace(' ·', '')}`;
  if (window.phase === 'sale') return `DAY ${window.degenesisDay} OF ${DEGENESIS_DAYS} · CLOSES IN${left.replace(' ·', '')}`;
  return '';
}

/**
 * The player's Degenesis orders (chain route /degenesis/orders): newest first, each
 * `{degenesisDay, orderIndex, amountRawWei, resolved: null | {flip, dgnrs, wwxrp, normalPasses, highPasses}}`.
 */
export async function readDegenesisOrders(player, { fetch: fetcher } = {}) {
  if (!player) return [];
  const load = fetcher ?? (await import('./api.js')).fetchJSON;
  const result = await load(`/degenesis/orders?player=${encodeURIComponent(String(player).toLowerCase())}`, { force: true });
  return Array.isArray(result?.items) ? result.items : [];
}
